import * as React from "react"
import { Link } from "gatsby"
import { HardHat, ArrowRight } from "./Icons"
import { useAuth } from "../context/auth"
import * as s from "./Header.module.css"

const LINKS = [
  { label: "Free Services", href: "/#services" },
  { label: "Website Builder", href: "/website-builder" },
  { label: "Invoice Builder", href: "/invoice-builder" },
  { label: "QR Codes", href: "/qr-codes" },
  
]

const Header = () => {
  const [open, setOpen] = React.useState(false)
  const { user, ready, available } = useAuth()

  // Until the session has resolved, show NEITHER "Log in" nor "Account".
  // Guessing wrong makes the header flip a moment after load, which reads as a
  // glitch to everyone and as a logout to anyone who was signed in.
  const account = !available || !ready ? null : user ? "in" : "out"

  return (
    <header className={s.header} data-print="hide">
      <div className={`container ${s.inner}`}>
        <a href="/" className={s.logo} aria-label="Free Contractor Services — home">
          <HardHat className={s.logoMark} />
          <span className={s.logoText}>
            <span>Free Contractor</span>
            <span>Services.com</span>
          </span>
        </a>

        <div className={`${s.menu} ${open ? s.menuOpen : ""}`}>
          <nav className={s.nav} aria-label="Primary">
            {LINKS.map(link => (
              <a key={link.label} href={link.href} onClick={() => setOpen(false)}>
                {link.label}
              </a>
            ))}
          </nav>

          <span className={s.actions}>
            {account === "in" ? (
              <Link to="/account" className={s.account}>
                Account
              </Link>
            ) : account === "out" ? (
              <Link to="/log-in" className={s.account}>
                Log in
              </Link>
            ) : null}

            <Link to="/website-builder" className={`btn btn--sm ${s.cta}`}>
              Get Started Free
              <ArrowRight className="btn__arrow" />
            </Link>
          </span>
        </div>

        <button
          type="button"
          className={s.toggle}
          aria-expanded={open}
          aria-label={open ? "Close menu" : "Open menu"}
          onClick={() => setOpen(v => !v)}
        >
          <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
            {open ? <path d="M4 4l12 12M16 4L4 16" /> : <path d="M2 5h16M2 10h16M2 15h16" />}
          </svg>
        </button>
      </div>
    </header>
  )
}

export default Header
